CREATE OR REPLACE FUNCTION public.geocode_city_approx(_city text) RETURNS TABLE(lat double precision, lng double precision) LANGUAGE sql IMMUTABLE SET search_path = public AS $function$ SELECT lat, lng FROM (VALUES ('paris', 48.8566, 2.3522), ('london', 51.5074, -0.1278), ('dubai', 25.2048, 55.2708), ('marrakech', 31.6295, -7.9811), ('phuket', 7.8804, 98.3923), ('bangkok', 13.7563, 100.5018), ('new york', 40.7128, -74.0060), ('los angeles', 34.0522, -118.2437), ('miami', 25.7617, -80.1918), ('casablanca', 33.5731, -7.5898), ('compiegne', 49.4178, 2.8264), ('lyon', 45.7640, 4.8357), ('marseille', 43.2965, 5.3698), ('nice', 43.7102, 7.2620), ('berlin', 52.5200, 13.4050), ('madrid', 40.4168, -3.7038), ('barcelona', 41.3851, 2.1734), ('rome', 41.9028, 12.4964), ('lisbon', 38.7223, -9.1393), ('amsterdam', 52.3676, 4.9041), ('singapore', 1.3521, 103.8198), ('tokyo', 35.6762, 139.6503), ('sydney', -33.8688, 151.2093), ('istanbul', 41.0082, 28.9784), ('cairo', 30.0444, 31.2357), ('cape town', -33.9249, 18.4241), ('montreal', 45.5017, -73.5673), ('toronto', 43.6532, -79.3832), ('mexico city', 19.4326, -99.1332), ('sao paulo', -23.5505, -46.6333) ) AS cities(city_name, lat, lng) WHERE LOWER(_city) LIKE '%' || city_name || '%' LIMIT 1; $function$;